draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw stick figure with round head
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30, H/2 + 70);
  ctx.stroke();

  // draw awareness circle
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.setLineDash([10, 10]);
  ctx.stroke();
  ctx.setLineDash([]);

  // draw thought bubbles
  ctx.beginPath();
  ctx.arc(W/2 + 70 * Math.cos(t), H/2 + 30 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 50 * Math.cos(t + Math.PI/2), H/2 + 50 * Math.sin(t + Math.PI/2), 10, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
